import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test, type TestContext } from "node:test";
import { decideStatus, parseEvent, processEvent } from "../src/refunds.ts";
import { buildApp, loadPaygateConfig } from "../src/server.ts";
import { Store } from "../src/store.ts";
import { computeSignature, SignatureError, verifyReplay, verifyWebhook } from "../src/verify.ts";

const SECRET = "whsec_test_pay381";
const NOW = 1731920000;
const POLICY = { auto_approve_max_minor: 500000, auto_approve_currencies: ["INR"] };

function event(id: string, type = "refund.requested", data: Record<string, unknown> = {}) {
  return { event_id: id, type, created: NOW,
    data: { refund_id: "rf_1", payment_id: "pay_1", amount: 500000, currency: "INR", ...data } };
}

function signature(body: string | Buffer, timestamp = Math.floor(Date.now() / 1000), secret = SECRET) {
  return `t=${timestamp},v1=${computeSignature(secret, timestamp, body)}`;
}

function diskState(dir: string): Record<string, string> {
  const files: Record<string, string> = {};
  function visit(path: string) {
    for (const name of readdirSync(path)) {
      const file = join(path, name);
      if (statSync(file).isDirectory()) visit(file);
      else files[file] = readFileSync(file).toString("hex");
    }
  }
  visit(dir);
  return files;
}

async function app(t: TestContext) {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  const store = new Store(dir);
  const handle = buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: ["retired-secret", SECRET], tolerance_s: 300 });
  const server = createServer((req, res) => void handle(req, res));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(async () => {
    server.closeAllConnections();
    await new Promise<void>((resolve) => server.close(() => resolve()));
    rmSync(dir, { recursive: true, force: true });
  });
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/webhooks/paygate`;
  return { dir, store, post: (body: string, headers: Record<string, string> = {}) =>
    fetch(url, { method: "POST", headers, body }) };
}

test("rotation accepts any signature against any configured secret", () => {
  const body = JSON.stringify(event("rotation"));
  const good = computeSignature(SECRET, NOW, body);
  const bad = "0".repeat(64);
  for (const signatures of [`v1=${bad},v1=${good}`, `v1=${good},v1=${bad}`]) {
    for (const secrets of [["old", SECRET], [SECRET, "old"]]) {
      assert.doesNotThrow(() => verifyWebhook(body, `t=${NOW},${signatures}`, secrets, NOW));
      assert.doesNotThrow(() => verifyReplay(body, String(NOW), signatures, secrets, NOW));
    }
  }
});

test("signatures cover exact whitespace and raw bytes", () => {
  const body = JSON.stringify(event("bytes"), null, 2) + "\n";
  const header = signature(body, NOW);
  assert.doesNotThrow(() => verifyWebhook(body, header, [SECRET], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(body)), header, [SECRET], NOW), SignatureError);
  const bytes = Buffer.from([0x00, 0x80, 0xff, 0x0a]);
  assert.doesNotThrow(() => verifyWebhook(bytes, signature(bytes, NOW), [SECRET], NOW));
  assert.throws(() => verifyWebhook(bytes.toString("utf8"), signature(bytes, NOW), [SECRET], NOW), SignatureError);
});

test("freshness is inclusive at 300 seconds in either direction", () => {
  const body = "{}";
  for (const offset of [-300, 300]) {
    assert.doesNotThrow(() => verifyWebhook(body, signature(body, NOW + offset), [SECRET], NOW));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook(body, signature(body, NOW + offset), [SECRET], NOW), SignatureError);
    assert.throws(() => verifyReplay(body, String(NOW + offset),
      `v1=${computeSignature(SECRET, NOW + offset, body)}`, [SECRET], NOW), SignatureError);
  }
});

test("malformed headers and empty secret configuration fail closed", () => {
  const body = "{}";
  for (const header of [undefined, "", "v1=" + "a".repeat(64), `t=${NOW}`, `t=NaN,v1=${"a".repeat(64)}`,
    `t=${NOW},t=${NOW},v1=${"a".repeat(64)}`, `t=${NOW},v1=abc`,
    `t=${"9".repeat(400)},v1=${"a".repeat(64)}`, `t=${NOW},v1=${"A".repeat(64)}`]) {
    assert.throws(() => verifyWebhook(body, header, [SECRET], NOW), SignatureError);
  }
  assert.throws(() => verifyWebhook(body, signature(body, NOW), [], NOW), SignatureError);
});

test("unauthenticated requests do not change refunds, raw events, markers, or audit", async (t) => {
  const { dir, post } = await app(t);
  const body = JSON.stringify(event("unauthenticated"));
  const before = diskState(dir);
  const now = Math.floor(Date.now() / 1000);
  const headers = [
    {},
    { "paygate-signature": signature(body, now, "wrong") },
    { "paygate-signature": signature(body, now - 3600) },
    { "paygate-signature": signature(body, now + 3600) },
    { "paygate-signature": signature(body), "x-replay-timestamp": String(now) },
    { "paygate-signature": signature(body), "x-replay-timestamp": String(now),
      "x-replay-signature": `v1=${computeSignature("wrong", now, body)}` },
    { "paygate-signature": signature(body), "x-replay-timestamp": String(now - 3600),
      "x-replay-signature": `v1=${computeSignature(SECRET, now - 3600, body)}` },
    { "paygate-signature": signature(body), "x-replay-timestamp": "not-a-timestamp",
      "x-replay-signature": `v1=${"0".repeat(64)}` },
  ];
  for (const header of headers) {
    const res = await post(body, header);
    assert.equal(res.status, 401);
    await res.json();
    assert.deepEqual(diskState(dir), before);
  }
  const altered = await post(body + " ", { "paygate-signature": signature(body) });
  assert.equal(altered.status, 401);
  assert.deepEqual(diskState(dir), before);
});

test("signed malformed events return 400; unknown types are ignored and deduplicated", async (t) => {
  const { post, store } = await app(t);
  for (const body of ["{", "null", "[]", "{}", JSON.stringify({ ...event("invalid"), created: "bad" }),
    JSON.stringify(event("invalid", "refund.requested", { amount: -1 })),
    JSON.stringify(event("invalid", "refund.cancelled", { refund_id: "" }))]) {
    const res = await post(body, { "paygate-signature": signature(body) });
    assert.equal(res.status, 400);
    assert.equal(store.isProcessed("invalid"), false);
    await res.json();
  }
  const body = JSON.stringify({ event_id: "unknown", type: "payment.updated", created: NOW });
  const first = await post(body, { "paygate-signature": signature(body) });
  assert.equal(first.status, 200);
  assert.deepEqual(await first.json(), { received: true, duplicate: false });
  const second = await post(body, { "paygate-signature": signature(body) });
  assert.deepEqual(await second.json(), { received: true, duplicate: true });
  assert.equal(store.listRefunds().length, 0);
});

test("duplicates preserve original raw body, refunds, audit and persistent markers", async (t) => {
  const { post, store, dir } = await app(t);
  const body = JSON.stringify(event("persistent"), null, 2) + "\n";
  const first = await post(body, { "paygate-signature": signature(body) });
  assert.deepEqual(await first.json(), { received: true, duplicate: false });
  const before = diskState(dir);
  const changed = JSON.stringify(event("persistent", "refund.requested", { amount: 900000 }));
  const deliveries = await Promise.all(Array.from({ length: 4 }, () =>
    post(changed, { "paygate-signature": signature(changed) })));
  for (const delivery of deliveries) {
    assert.equal(delivery.status, 200);
    assert.deepEqual(await delivery.json(), { received: true, duplicate: true });
  }
  assert.deepEqual(diskState(dir), before);
  assert.equal(store.loadRawEvent("persistent"), body);
  const reopened = new Store(dir);
  assert.deepEqual(processEvent(reopened, POLICY, parseEvent(changed)), { outcome: "duplicate" });
  assert.equal(reopened.listRefunds().length, 1);
  assert.deepEqual(diskState(dir), before);
  const forged = await post(changed, { "paygate-signature": signature(changed, undefined, "wrong") });
  assert.equal(forged.status, 401);
  assert.deepEqual(diskState(dir), before);
});

test("replays use their fresh signature, not the original signature, and deduplicate", async (t) => {
  const { post, dir, store } = await app(t);
  const body = JSON.stringify(event("replay"));
  const now = Math.floor(Date.now() / 1000);
  const replayHeaders = { "x-replay-timestamp": String(now),
    "x-replay-signature": `v1=${computeSignature(SECRET, now, body)}` };
  // No original signature is needed to authenticate a replay.
  const first = await post(body, replayHeaders);
  assert.equal(first.status, 200);
  assert.deepEqual(await first.json(), { received: true, duplicate: false });
  const before = diskState(dir);
  const second = await post(body, { ...replayHeaders, "paygate-signature": "invalid-original" });
  assert.deepEqual(await second.json(), { received: true, duplicate: true });
  assert.equal(store.listRefunds().length, 1);
  assert.deepEqual(diskState(dir), before);
});

test("cancellation and ignored cancellation are audited only once", async (t) => {
  const { store, dir } = await app(t);
  processEvent(store, POLICY, event("request", "refund.requested", { amount: 500001 }));
  const cancel = event("cancel", "refund.cancelled");
  processEvent(store, POLICY, cancel);
  assert.equal(store.listRefunds()[0].status, "cancelled");
  const cancelled = diskState(dir);
  assert.deepEqual(processEvent(store, POLICY, cancel), { outcome: "duplicate" });
  assert.deepEqual(diskState(dir), cancelled);
  processEvent(store, POLICY, event("small", "refund.requested", { refund_id: "rf_small" }));
  const ignored = event("cancel_small", "refund.cancelled", { refund_id: "rf_small" });
  assert.equal(processEvent(store, POLICY, ignored).outcome, "ignored");
  const audited = diskState(dir);
  assert.deepEqual(processEvent(store, POLICY, ignored), { outcome: "duplicate" });
  assert.deepEqual(diskState(dir), audited);
  assert.equal(store.findByPaygateId("rf_small")[0].status, "auto_approved");
});

test("event IDs are own-property keys, including inherited object names", async (t) => {
  const { store, dir } = await app(t);
  for (const id of ["constructor", "toString", "__proto__"]) {
    assert.equal(processEvent(store, POLICY, event(id)).outcome, "processed");
    assert.equal(processEvent(new Store(dir), POLICY, event(id)).outcome, "duplicate");
  }
  assert.equal(store.listRefunds().length, 3);
});

test("on-call policy is INR only, inclusive at ₹5,000, with a 300-second signature window", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 499999, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
  assert.equal(loadPaygateConfig().tolerance_s, 300);
});
